      n=action==='jump'?Number($(`[data-jump-input="${audit?'audit':'main'}"]`).value):n+(action==='next'?1:-1);if(!Number.isInteger(n)||n<1||n>pages)return toast('请输入 1 至 '+pages+' 的页码',true);if(audit)auditPage=n;else{query.number=n;selected=null;}render();return;
