    if(action==='review') {const r=db.reviews.find(r=>r.id===id);if(actor!=='reviewer'||r.status!=='待内部审核')return;if(r.submitter===actor)return toast('不能审核本人提交的申请',true);open('商户审核操作',details([['商户',r.merchant],['申请类型',r.kind],['申请版本',r.version],['提交人',r.submitter],['变更内容',r.changed||'完整资料'],['原资料',r.oldValue||'—'],['新资料',r.newValue||'—']])+`<label class="field">审核意见<textarea id="reviewNote" placeholder="拒绝时必须填写原因"></textarea></label>`,B('取消','close')+B('拒绝','reviewReject',id)+B('通过','reviewPass',id,true));return;}
    if(['reviewPass','reviewReject'].includes(action)){const r=db.reviews.find(r=>r.id===id);if(actor!=='reviewer'||r.submitter===actor||r.status!=='待内部审核')return error('当前不可审核');const note=$('#reviewNote').value.trim();if(action==='reviewReject'&&!note)return error('请填写拒绝原因');r.reason=note;r.status=action==='reviewPass'?'内部审核通过':'内部驳回';r.reviewed=now();const m=merchantFor(r.merchantId);if(m){if(action==='reviewPass'&&r.pending)Object.assign(m,r.pending);m.review=r.status;if(action==='reviewPass'){m.version=r.version;if(r.kind==='资料修改')db.lifecycle.unshift({id:uid('LC'),merchant:m.name,channel:m.tools[0],type:'商户资料变更',platform:(m.account||'平台审核版本')+' · '+r.version,effective:r.oldValue||'原渠道有效版本',status:'渠道处理中',time:now()});}}persist();close();render();toast('审核结果已保存');return;}
    if(action==='submitOnboarding') {const r=find(selected);if(!r||!mayMaintain())return;const m=merchantFor(r.merchantId);if(m.status==='已冻结'||m.review!=='内部审核通过')return toast('商户当前不满足申请条件',true);open('提交支付开通申请',details([['商户',r.merchant],['渠道',r.channel],['资料版本',r.version],['渠道字段映射','由渠道适配层转换并检查'],['资金处理','模拟渠道，不实际收付资金']]),B('取消','close')+B('确认提交','confirmOnboarding',r.id,true));return;}
    if(action==='confirmOnboarding'){const [mid,c]=id.split('|'),m=merchantFor(mid);if(!mayMaintain()||!m||m.review!=='内部审核通过'||m.status==='已冻结'||db.onboarding.some(a=>a.merchantId===mid&&a.channel===c&&['审核中','已通过'].includes(a.status)))return error('商户状态已变化或申请已存在，请刷新');db.onboarding.unshift({id:uid('AP'),merchant:m.name,merchantId:mid,channel:c,status:'审核中',version:m.version,time:now()});persist();close();selected=null;currentTab='records';render();toast('模拟申请已提交');return;}
    if(action==='progress'){const r=db.onboarding.find(a=>a.id===id);r.status='已通过';r.channelMerchant='MOCK-'+r.id;persist();render();toast('模拟渠道反馈：审核通过');return;}
    if(action==='channelChange'){const r=db.lifecycle.find(r=>r.id===id);if(!mayMaintain())return;r.status='渠道变更成功';r.effective=r.platform;persist();render();toast('渠道确认成功，已切换有效资料');return;}
