    if(action==='saveOrder'){const v=genericValues();if(!v||!mayTrade())return;const m=db.merchants.find(m=>m.name===v.merchantId),cf=db.channelConfig.find(c=>c.channel===v.channel);if(!m||m.status!=='已开通'||!m.tools.includes(v.channel))return error('商户或支付工具当前不可交易');if(!db.onboarding.some(a=>a.merchantId===m.id&&a.channel===v.channel&&a.status==='已通过'))return error('所选支付工具尚未获渠道批准');if(actor==='merchant'&&m.id!=='M1001')return error('不能为其他商户下单');if(cf.fee===''||cf.status!=='启用')return error('渠道未启用或手续费率未配置');if(!(Number(v.amount)>0)||round(Number(v.amount))!==Number(v.amount))return error('金额必须大于零，最多两位小数');if(Number(m.fee)+Number(cf.fee)>100)return error('费用不可超过实付金额');const old=db.orders.find(o=>o.merchantId===m.id&&o.merchantOrder===v.merchantOrder);if(old){if(old.amount!==Number(v.amount)||old.channel!==v.channel||old.customer!==v.customer)return error('相同商户订单号的请求参数发生冲突');close();orderDetail(old);return;}
      if(db.closedChannels.includes(m.id+'|'+v.channel))return error('该商户渠道已关闭，不能发起新交易');
      db.orders.unshift({id:uid('BO'),payment:uid('PO'),merchantId:m.id,merchant:m.name,merchantOrder:v.merchantOrder,customer:v.customer,channel:v.channel,amount:Number(v.amount),status:'待支付',created:now(),feeRate:Number(m.fee)||0,channelRate:Number(cf.fee),sharing:m.sharing,attempts:0});persist();close();render();toast('业务订单已创建，费用快照已保存');return;}
    if(action==='pay'){const o=orderFor(id);if(o&&o.status==='待支付'&&o.payStatus!=='结果未知')paymentDialog(o);return;}
    if(action==='confirmPayment'){const o=orderFor(id);if(!mayTrade()||o.status!=='待支付'||o.payStatus==='结果未知')return error('当前订单不可再次支付');const result=$('#paymentResult').value;o.attempts++;o.payStatus=result==='unknown'?'结果未知':result==='failed'?'已失败':'已成功';if(result==='success')applyPayment(o);if(result==='unknown')o.channelConfirmed=true;persist();close();render();toast(result==='unknown'?'渠道已受理，本地结果未知，须先查单':result==='failed'?'渠道确认失败，保留尝试记录':'支付成功，清分与分账已生成');return;}
