    if(action==='confirmFunding'){const r=db.refunds.find(r=>r.id===id);if(!mayFinance()||r.status!=='待补差')return error('退款状态已变化');if(!$('#fundingNo').value.trim())return error('请填写补差请求号');r.fundingNo=$('#fundingNo').value;r.status='已成功';r.gap=0;const o=orderFor(r.order);if(o)o.status='已退款';db.exceptions.filter(e=>e.source===r.id).forEach(e=>e.status='已恢复');persist();close();render();toast('补差已记录，原退款继续成功');return;}
